INSERT INTO escalation VALUES(4,'Robertson',NULL,NULL,13.83999999999999986,'2017-01-01 00:00:00');
INSERT INTO facility VALUES(1,'Electrical Equipment','Including switchgear, station service equipment, switchboards, protective equipment, electrical raceways, conduit, and wiring.','24','PWR-12-BE','1978-01-01 00:00:00','2017-01-01 00:00:00','EEDB',2.849406500000000175);
INSERT INTO facility VALUES(2,'Heat Rejection Equipment','Including heat rejection equipment.','25','PWR-12-BE','1978-01-01 00:00:00','2017-01-01 00:00:00','EEDB',2.849406500000000175);
INSERT INTO facility VALUES(3,'Miscellaneous Equipment','Including air, water, and steam service systems. Other accounts cover lift equipment, communications equipment, fixtures and furnishings, and wastewater processing','26','PWR-12-BE','1978-01-01 00:00:00','2017-01-01 00:00:00','EEDB',2.849406500000000175);
INSERT INTO facility VALUES(4,'Reactor Plant Equipment','Reactor plant equipment, including the reactor equipment itself, main heat transfer systems, reactor safety (safeguards) equipment, radioactive waste processing systems, fuel handling and storage systems, reactor instrumentation and control hardware, and other reactor plant equipment.','22','PWR-12-BE','1978-01-01 00:00:00','2017-01-01 00:00:00','EEDB',2.849406500000000175);
INSERT INTO facility VALUES(5,'Structures and Improvements','Site preparation and yardwork, and construction of the various buildings and structures on the site. Building estimates generally cover excavation, subsurface concrete, and superstructures. Also cover standard building services but not process-related piping, ventilation, and equipment.','21','PWR-12-BE','1978-01-01 00:00:00','2017-01-01 00:00:00','EEDB',2.849406500000000175);
INSERT INTO facility VALUES(6,'Turbine-Generator Equipment','Turbine generator equipment, beginning with supercritical fluid or steam from steam generators (PWR) or salt-to-water heat transfer equipment (AHTR) and ending with electricity at the generator outputs.','23','PWR-12-BE','1978-01-01 00:00:00','2017-01-01 00:00:00','EEDB',2.849406500000000175);
