INSERT INTO fusion_acco VALUES(90,'26','Heat rejection system cost',50520149.78000000119,1,'2','Unchanged',0.00914568500000000062,'acc26','million','ireactor, powfmw, pinjwp, tfcmw, pthermmw, pgrossmw, uchrs, lsa');
INSERT INTO fusion_alg VALUES(1,'acc211','c','Site_improvements,_facilities,_land_(M$)','FusionFunc','acc211= csi*cmlsa[lsa-1] + cland','million');
INSERT INTO fusion_alg VALUES(2,'acc212','c','Reactor_building_cost_(M$)','FusionFunc','acc212= (1.0e-6*ucrb*rbvol)**exprb* cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(3,'acc213','c','Turbine_building_cost_(M$)','FusionFunc',' if ireactor == 1:\n        acc213 = cturbb * cmlsa[lsa - 1]\n    else: acc213 = 0.0e0','million');
INSERT INTO fusion_alg VALUES(4,'acc2141','c','Reactor_maintenance_building_cost_(M$)','FusionFunc','acc2142 = 1.0e-6*ucmb*rmbvol**exprb*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(5,'acc2142','c','Warm_shop_cost_(M$)','FusionFunc','acc2142 = (1.0e-6*ucws*wsvol)**exprb*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(6,'acc215','c','Tritium_building_cost_(M$)','FusionFunc','acc215 = ((1.0e-6*uctr*triv)*exprb)*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(7,'acc216','c','Electrical_equipment_building_cost_(M$)','FusionFunc','acc216 = 1.0e-6*ucel*elevol**exprb*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(8,'acc2171','c','Additional_buildings_cost_(M$)','FusionFunc','acc2171 = 1.0e-6*ucad*admvol**exprb* cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(9,'acc2172','c','Control_room_buildings_cost_(M$)','FusionFunc','acc2172 = 1.0e-6*ucconc*convol**exprb* cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(10,'acc2173','c','Shop_and_warehouses_cost_(M$)','FusionFunc','acc2173 = 1.0e-6*ucsh*shovol**exprb*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(11,'acc2174','c','Cryogenic_building_cost_(M$)','FusionFunc','acc2174 = 1.0e-6*uccr*cryvol**exprb*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(12,'acc2211','c','First_wall_cost_(M$)','FusionFunc','if ife == 1:\n        acc2211 = (1.0e-6*cmlsa[lsa - 1]\n            *  (ucblss*(fwmatm(1, 1)+ fwmatm(2, 1)+ fwmatm(3, 1))\n            + uccarb*(fwmatm(1, 2)+ fwmatm(2, 2)+ fwmatm(3, 2))\n            + ucblli2o*(fwmatm(1, 4) + fwmatm(2, 4)+ fwmatm(3, 4))\n            + ucconc*(fwmatm(1, 5)+ fwmatm(2, 5)+ fwmatm(3, 5))))\n    else:\n        acc2211 = (1.0e-6* cmlsa[lsa - 1]*((ucfwa + ucfws)* fwarea+ ucfwps)) \n    acc2211 = fkind * acc2211\n    if ifueltyp == 1:\n        acc2211 = 0\n        acc2211 = fwallcst\n    elif ifueltyp == 2:\n        fwallcst = acc2211\n    else:\n        fwallcst = 0.0e0','million');
INSERT INTO fusion_alg VALUES(13,'acc22121','c','Blanket_beryllium_cost_(M$)','FusionFunc','if ife == 1:\n        acc22121 = 0\n    else:\n        if iblanket == 4:\n            acc22121 = 1.0e-6*wtbllipb*ucbllipb\n        else:\n            acc22121 = 1.0e-6*whtblbe*ucblbe\n    acc22121 = fkind*acc22121*cmlsa[lsa-1]','million');
INSERT INTO fusion_alg VALUES(14,'acc22122','c','Blanket_breeder_material_cost_(M$)','FusionFunc','if ife == 1:\n        if iblanket == 4:\n            acc22122 = 1.0e-6*whtblli*ucblli\n        else:\n            if iblanket == 2:\n                acc22122 = 1.0e-6*whtblbreed*ucblbreed\n            else:\n                acc22122 = 1.0e-6*wtblli2o*ucblli2o\n    else:\n        acc22122 = 1.0e-6*wtblli2o*ucblli2o\n    acc22122 =fkind*acc22122*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(15,'acc22123','c','Blanket_stainless_steel_cost_(M$)','FusionFunc','acc22123 = acc22123 = 1.0e-6*whtblss*ucblss\n acc22123 = fkind*acc22123*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(16,'acc22124','c','Blanket_vanadium_cost_(M$)','FusionFunc','if ife == 1:\n        acc22124 = 1.0e-6*whtblvd*ucblvd\n else:\n        acc22124 = 0\n  acc22124 = fkind*acc22124*cmlsa[lsa-1]\n  return acc22124','million');
INSERT INTO fusion_alg VALUES(17,'acc22131','c','Bulk_shield_cost_(M$)','FusionFunc','if ife == 1:\n        acc22131 = 1.0e-6*cmlsa[lsa - 1]*ucshld*(shmatm[1, 0] + shmatm[2, 0]+shmatm[3, 0])\n        + uccarb*(shmatm[1, 1]+ shmatm[2, 1]+ shmatm[3, 1])\n        + ucblli2o*(shmatm[1, 1]+ shmatm[2, 1]+ shmatm[3, 1])\n        + ucconc* (shmatm[1, 1] + shmatm[2, 1]+ shmatm[3, 1]) \n    else:\n        acc22131 = 1.0e-6*whtshld*ucshld*cmlsa[lsa - 1] \n    acc22131 = fkind*acc22131','million');
INSERT INTO fusion_alg VALUES(18,'acc22132','c','Penetration_shielding_cost_(M$)','FusionFunc','if ife == 1:\n        acc22132 = 1.0e-6*wpenshld*ucpens* cmlsa[lsa - 1]\n    else:\n        acc22132 = 1.0e-6*wpenshld*ucpens* cmlsa[lsa - 1]\n    acc22132 = fkind*acc22132','million');
INSERT INTO fusion_alg VALUES(19,'acc2214','c','Total_support_structure_cost_(M$)','FusionFunc','acc2214 = 1.0e-6*gsmass*ucgss*cmlsa[lsa - 1]\n    acc2214 = fkind*acc2214','million');
INSERT INTO fusion_alg VALUES(20,'acc2215','c','Divertor_cost_(M$)','FusionFunc','if ife == 1:\n        acc2215 = 0\n        divcst = 0\n    else:\n        acc2215 = 1.0e-6 * divsur * ucdiv\n        acc2215 = fkind * acc2215\n        if ifueltyp == 1:\n            acc2215 = 0\n            acc2215 = divcst \n        elif ifueltyp == 2:\n            divcst = acc2215\n        else:\n            divcst = 0.0e0 ','million');
INSERT INTO fusion_alg VALUES(21,'acc22211','c','TF_coil_conductor_cost_(M$)','FusionFunc','if i_tf_sup == 1:  \n        costtfsc = ucsc[i_tf_sc_mat - 1]*whtconsc/(tfleng*n_tf_turn)\n        costtfcu = uccu*whtconcu/(tfleng*n_tf_turn)\n        costwire = costtfsc+costtfcu\n        ctfconpm = costwire+cconshtf+cconfix\n        acc22211 = 1.0e-6*ctfconpm*n_tf*tfleng*n_tf_turn\n        acc22211 = fkind*acc22211*cmlsa[lsa - 1]\n    else:  \n        acc22211 = 1.0e-6*whtcp*uccpcl1*cmlsa[lsa - 1]\n        acc22211 = fkind*acc22211\n        if (itart == 1) and (ifueltyp == 1):\n            acc22211 = cpstcst\n            accc22211 = 0.0e0\n        elif (itart == 1) and (ifueltyp == 2):\n            acc22211 = cpstcst','million');
INSERT INTO fusion_alg VALUES(22,'acc22212','c','TF_coil_winding_cost_(M$)','FusionFunc','if i_tf_sup == 1:\n        acc22212 = 1.0e-6*ucwindtf*n_tf*tfleng*n_tf_turn\n        acc22212 = fkind*acc22212*cmlsa[lsa-1]\n    else:\n        acc22212 = 1.0e-6*whttflgs*uccpclb*cmlsa[lsa - 1]\n        acc22212 = fkind*acc22212','million');
INSERT INTO fusion_alg VALUES(23,'acc22213','c','TF_coil_case_cost_(M$)','FusionFunc',' if i_tf_sup == 1:\n        acc22213 = 1.0e-6*(whtcas*uccase)*n_tf\n        acc22213 = fkind*acc22213*cmlsa[lsa - 1]\n    else:\n        acc22213 = 0','million');
INSERT INTO fusion_alg VALUES(24,'acc22214','c','TF_intercoil_structure_cost_(M$)','FusionFunc','if i_tf_sup == 1:\n        acc22214 = 1.0e-6*aintmass*ucint\n        acc22214 = fkind*acc22214*cmlsa[lsa - 1]\n    else:\n        acc22214 = 0','million');
INSERT INTO fusion_alg VALUES(25,'acc22215','c','TF_coil_gravity_support_structure_(M$)','FusionFunc','if i_tf_sup == 1:\n        acc22215 = 1.0e-6*clgsmass*ucgss\n        acc22215 = fkind*acc22215*cmlsa[lsa - 1]\n    else:\n        acc22215 = 0','million');
INSERT INTO fusion_alg VALUES(26,'acc22221','c','PF_coil_conductor_cost_(M$)','FusionFunc',NULL,'million');
INSERT INTO fusion_alg VALUES(27,'acc22222','c','PF_coil_winding_cost_(M$)','FusionFunc','for i in range(0, nohc):\n        pfwndl = pfwndl +(twopi*rpf[i] *turns[i])\n    acc22222 = 1.0e-6*ucwindpf*pfwndl\n    acc22222 = fkind*acc22222*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(28,'acc22223','c','PF_coil_case_cost_(M$)','FusionFunc','acc22223 = 1.0e-6*uccase*whtpfs\n    acc22223 = fkind*acc22223*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(29,'acc22224','c','PF_coil_support_structure_cost_(M$)','FusionFunc','acc22224 = 1.0e-6*ucfnc*fncmass\n    acc22224 = fkind*acc22224*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(30,'acc2223','c','Vacuum_vessel_assembly_cost_(M$)','FusionFunc','acc2223 = 1.0e-6*vvmass*uccryo\n    acc2223 = fkind*acc2223*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(31,'acc2231','c','ECH_system_cost_(M$)','FusionFunc',NULL,'million');
INSERT INTO fusion_alg VALUES(32,'acc2232','c','Lower_hybrid_system_cost_(M$)','FusionFunc','if ife == 1:\n        if iefrf == 2:\n            acc2232 = (1.0e-6*uclh*(1.0e6*plhybd)**exprf)\n        else:\n            acc2232 = (1.0e-6*ucich*(1.0e6*plhybd)**exprf)\n            if ifueltyp == 1:\n                acc2232 = (1.0e0-fcdfuel)*acc2232\n                acc2232 = fkind * acc2232\n    else:\n        if ifueltyp == 1:\n            acc2232 = 0.0e0','million');
INSERT INTO fusion_alg VALUES(33,'acc2233','c','Neutral_beam_system_cost_(M$)','FusionFunc','if ife == 1:\n            acc2233 = (1.0e-6*ucnbi*(1.0e6*pnbitot)**exprf)\n            if ifueltyp == 1:\n                acc2233 = (1.0e0-fcdfuel)*acc2233\n                acc2233 = fkind*acc2233\n    else:\n            if ifedrv == 2:\n                acc2233 = 0.0e0','million');
INSERT INTO fusion_alg VALUES(34,'acc2241','c','High_vacuum_pumps_cost_(M$)','FusionFunc','if ntype == 1:\n        acc2241 = 1.0e-6*vpumpn*uccpmp\n    else:\n        acc2241 = 1.0e-6*vpumpn*uctpmp\n    acc2241 = fkind*acc2241','million');
INSERT INTO fusion_alg VALUES(35,'acc2242','c','Backing_pumps_cost_(M$)','FusionFunc','acc2242 = 1.0e-6*nvduct*ucbpmp\n    acc2242 = fkind*acc2242 ','million');
INSERT INTO fusion_alg VALUES(36,'acc2243','c','Vacuum_duct_cost_(M$)','FusionFunc',NULL,'million');
INSERT INTO fusion_alg VALUES(37,'acc2244','c','Valves_cost_(M$)','FusionFunc','acc2244 = 1.0e-6*2.0e0*nvduct*((vcdimax*1.2e0)**1.4e0)*ucvalv\n    acc2244 = fkind*acc2244','million');
INSERT INTO fusion_alg VALUES(38,'acc2245','c','Duct_shielding_cost_(M$)','FusionFunc','acc2245 = 1.0e-6*nvduct*vacdshm*ucvdsh\n    acc2245 = fkind*acc2245','million');
INSERT INTO fusion_alg VALUES(39,'acc2246','c','Instrumentation_cost_(M$)','FusionFunc','acc2246 = 1.0e-6*ucviac\n    acc2246 = fkind*acc2246','million');
INSERT INTO fusion_alg VALUES(40,'acc22511','c','TF_coil_power_supplies_cost_(M$)','FusionFunc','acc22511 = 1.0e-6*uctfps*(tfckw*1.0e3+tfcmw*1.0e6)**expel\n    acc22511 = fkind*acc22511','million');
INSERT INTO fusion_alg VALUES(41,'acc22512','c','TF_coil_breakers_cost_(M$)','FusionFunc',' if i_tf_sup == 1:\n        acc22512 = 1.0e-6*(uctfbr*n_tf*(cpttf*vtfskv*1.0e3)**expel+uctfsw*cpttf)\n    else:\n        acc22512 = 0.0e0\n    acc22512 = fkind*acc22512','million');
INSERT INTO fusion_alg VALUES(42,'acc22513','c','TF_coil_dump_resistors_cost_(M$)','FusionFunc','acc22513 = 1.0e-6*(1.0e9*uctfdr*estotftgj+uctfgr*0.5e0*n_tf)\n    acc22513 = fkind*acc22513','million');
INSERT INTO fusion_alg VALUES(43,'acc22514','c','TF_coil_instrumentation_and_control_(M$)','FusionFunc','acc22514 = 1.0e-6*uctfic*(30.0e0*n_tf)\n    acc22514 = fkind*acc22514 ','million');
INSERT INTO fusion_alg VALUES(44,'acc22515','c','TF_coil_bussing_cost_(M$)','FusionFunc',' if i_tf_sup == 1:\n        acc22515 = 1.0e-6*ucbus*cpttf*tfbusl\n    else:\n        acc22515 = 1.0e-6*uctfbus*tfbusmas\n    acc22515 = fkind*acc22515','million');
INSERT INTO fusion_alg VALUES(45,'acc22521','c','PF_coil_power_supplies_cost_(M$)','FusionFunc',NULL,'million');
INSERT INTO fusion_alg VALUES(46,'acc22522','c','PF_coil_instrumentation_and_control_(M$)','FusionFunc','acc22522 = 1.0e-6*ucpfic*pfckts*30.0e0\n    acc22522 = fkind*acc22522','million');
INSERT INTO fusion_alg VALUES(47,'acc22523','c','PF_coil_bussing_cost_(M$)','FusionFunc','acc22523 = 1.0e-6*ucpfb*spfbusl*acptmax\n    acc22523 = fkind*acc22523','million');
INSERT INTO fusion_alg VALUES(48,'acc22524','c','PF_coil_burn_power_supplies_cost_(M$)','FusionFunc','if pfckts == 0:\n        acc22524 = 0.0e0\n    else:\n       acc22524 = 1.0e-6*ucpfbs*pfckts*(srcktpm/pfckts)**0.7e0\n    acc22524 = fkind*acc22524','million');
INSERT INTO fusion_alg VALUES(49,'acc22525','c','PF_coil_breakers_cost_(M$)','FusionFunc','acc22525 = 1.0e-6*ucpfbk*pfckts*((acptmax*vpfskv)**0.7e0)\n    acc22525 = fkind*acc22525','million');
INSERT INTO fusion_alg VALUES(50,'acc22526','c','PF_coil_dump_resistors_cost_(M$)','FusionFunc','acc22526 = 1.0e-6*ucpfdr1*ensxpfm\n    acc22526 = fkind*acc22526','million');
INSERT INTO fusion_alg VALUES(51,'acc22527','c','PF_coil_ac_breakers_cost_(M$)','FusionFunc',' acc22527 = 1.0e-6*ucpfcb*pfckts\n    acc22527 = fkind*acc22527','million');
INSERT INTO fusion_alg VALUES(52,'acc2253','c','Total,_energy_storage_cost_(M$)','FusionFunc','if lpulse == 1:\n        if istore == 1:\n            acc2253 = 0.1e0\n            acc2253 = acc2253 + 0.8e0\n            acc2253 = acc2253 + 4.0e0\n            acc2253 = acc2253 + 0.5e0\n            acc2253 = acc2253 + 2.8e0\n            acc2253 = acc2253 + 29.0e0\n        elif istore == 2:\n            acc2253 = 0.1e0\n            acc2253 = acc2253 + 0.8e0\n            acc2253 = acc2253 + 2.8e0\n            acc2253 = acc2253 + 4.0e0\n            acc2253 = acc2253 + 330.0e0\n            acc2253 = acc2253 + 1.0e0\n            acc2253 = acc2253 + 2.0e0\n            acc2253 = acc2253 + 18.0e0\n        elif istore == 3:\n            shcss = 520.0e0\n            acc2253 = ucblss*(pthermmw * 1.0e6)*tdown/(shcss*dtstor)\n    if istore < 3:\n        acc2253 = acc2253*pnetelmw / 1200.0e0\n        acc2253 = acc2253*1.36e0','million');
INSERT INTO fusion_alg VALUES(56,'acc2262','c','Total,_auxiliary_cooling_system_cost_(M$)','FusionFunc','cal_acc2262 = cal_accppa','million');
INSERT INTO fusion_alg VALUES(57,'acc2263','c','Total,_cryogenic_system_cost_(M$)','FusionFunc',NULL,'million');
INSERT INTO fusion_alg VALUES(58,'acc2271','c','Fuelling_system_cost_(M$)','FusionFunc','acc2271 = 1.0e-6*ucf1\n    acc2271 = fkind*acc2271','million');
INSERT INTO fusion_alg VALUES(59,'acc2272','c','Fuel_processing_and_purification_cost_(M$)','FusionFunc','if ife == 1:\n        targtm = (gain*edrive*3.0e0*1.67e-27*1.0e3)/(1.602e-19 * 17.6e6 * fburn)\n        wtgpd = targtm*reprat*86400.0e0\n    else:\n        wtgpd = 2.0e0*rndfuel*afuel*umass*1000.0e0*86400.0e0\n    acc2272 = 1.0e-6*ucfpr*(0.5e0+0.5e0*(wtgpd/60.0e0)**0.67e0)\n    acc2272 = fkind*acc2272','million');
INSERT INTO fusion_alg VALUES(60,'acc2273','c','Atmospheric_recovery_systems_cost_(M$)','FusionFunc','if ftrit > 1.0e-3:\n        acc2273 = (1.0e-6*ucdtc*((cfrht / 1.0e4) ** 0.6e0*(volrci+wsvol)))\n    else:\n        acc2273 = 0.0e0\n    acc2273 = fkind*acc2273','million');
INSERT INTO fusion_alg VALUES(61,'acc2274','c','Nuclear_building_ventilation_cost_(M$)','FusionFunc','acc2274 = 1.0e-6*ucnbv*(volrci+wsvol)**0.8e0\n    acc2274 =fkind*acc2274','million');
INSERT INTO fusion_alg VALUES(62,'acc228','c','Instrumentation_and_control_cost_(M$)','FusionFunc','acc228 = 1.0e-6*uciac\n    acc228 = fkind*acc228','million');
INSERT INTO fusion_alg VALUES(63,'acc229','c','Maintenance_equipment_cost_(M$)','FusionFunc','acc229 = 1.0e-6*ucme\n    acc229 = fkind*acc229','million');
INSERT INTO fusion_alg VALUES(64,'acc23','c','Turbine_plant_equipment_cost_(M$)','FusionFunc','if ireactor == 1:\n        acc23 = (1.0e-6*ucturb[coolwh - 1]*(pgrossmw / 1200.0e0)**exptpe)','million');
INSERT INTO fusion_alg VALUES(65,'acc241','c','Switchyard_equipment_cost_(M$)','FusionFunc','acc241 = 1.0e-6*ucswyd*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(66,'acc242','c','Transformers_cost_(M$)','FusionFunc','acc242 = 1.0e-6*((ucpp*(pacpmw* 1.0e3)**expepe)+ucap*(fcsht * 1.0e3))\n    acc242 = acc242 * cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(67,'acc243','c','Low_voltage_equipment_cost_(M$)','FusionFunc',NULL,'million');
INSERT INTO fusion_alg VALUES(68,'acc244','c','Diesel_backup_equipment_cost_(M$)','FusionFunc','acc244 = 1.0e-6*ucdgen*4.0e0*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(69,'acc245','c','Auxiliary_facilities_cost_(M$)','FusionFunc','acc245 = 1.0e-6*ucaf*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(70,'acc25','c','Miscellaneous_plant_equipment_cost_(M$)','FusionFunc','acc25 = 1.0e-6*ucmisc*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(71,'acc26','c','Heat_rejection_system_cost_(M$)','FusionFunc','if ireactor == 0:\n        pwrrej = powfmw+pinjwp+tfcmw\n    else:\n        pwrrej = pthermmw - pgrossmw\n    acc26 = (1.0e-6*uchrs*pwrrej)/ 2300.0e0*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(54,'acchx','c','Primary_heat_exchanger_cost_(M$)','FusionFunc','acchx = 1.0e-6*ucphx*nphx*(1.0e6*pthermmw/nphx)**exphts\n    acchx =fkind*acchx*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(53,'accpp','c','Pumps_and_piping_system_cost_(M$)','FusionFunc','accpp = 1.0e-6*uchts[coolwh-1]*((1.0e6*pfwdiv)**exphts+\n                                     (1.0e6*pnucblkt)**exphts+(1.0e6*pnucshld)**exphts)\n    accpp =fkind*accpp*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(55,'accppa','c','Pumps,_piping_cost_(M$)','FusionFunc','acccppa = (1.0e-6*ucahts*((1.0e6*pinjht)**exphts+(1.0e6*crypmw)**exphts+\n                (1.0e6*vachtmw)**exphts+(1.0e6*trithtmw)**exphts+(1.0e6*fachtmw)**exphts))\n    if ife == 1:\n        acccppa = acccppa+1.0e-6*ucahts*((1.0e6*tdspmw)**exphts\n                + (1.0e6*tfacmw)**exphts)\n    acccppa =fkind*acccppa*cmlsa[lsa - 1]','million');
INSERT INTO fusion_alg VALUES(73,'calaintmass','v','intercoil structure mass calculation','FusionFunc','calaintmass = 0.18e0 * st_f_b**2 * intercoil_surface * denstl','kg');
INSERT INTO fusion_alg VALUES(85,'calawpoh','v','central solenoid conductor+void area with area of steel subtracted calculation ','FusionFunc','areaspf = oh_steel_frac * areaoh\n    calawpoh = areaoh - areaspf','m2');
INSERT INTO fusion_alg VALUES(74,'calclgsmass','v','gravity support structure for TF coil, PF coil and intercoil support systems calculation','FusionFunc','calclgsmass = 0.2*aintmass','kg');
INSERT INTO fusion_alg VALUES(77,'caldlscal','v','system duct length scaling calcualtion','FusionFunc','caldlscal = l1 * d[imax] ** 1.4e0 + (ltot - l1) * (d[imax] * 1.2e0) ** 1.4e0',NULL);
INSERT INTO fusion_alg VALUES(76,'calechpwr','v','ECH power calculation','FusionFunc','calechpwr = (1.0e-6* (faccd - faccdfix)* plascur / effrfss)+ pheat','MW');
INSERT INTO fusion_alg VALUES(72,'calelevol','v','volume of electrical equipment building cost calculation','FusionFunc','calelevol = tfcbv + pfbldgm3 + esbldgm3 + pibv','m3');
INSERT INTO fusion_alg VALUES(75,'calfncmass','v','PF coil outer support fence mass calculation','FusionFunc','calfncmass = 2.1e-11 * ai * ai * r0 * akappa * a','kg');
INSERT INTO fusion_alg VALUES(78,'calgsmass','v','reactor core gravity support mass calculation','FusionFunc','ws1 = coolmass + fwmass + blmass + shldmass + dvrtmass\n    gsm1 = 5.0e0 * 9.807e0 * ws1 * dens / sigal\n    ws2 = ws1 + tfmass + pfmass + cal_calaintmass + clgsmass\n    gsm2 = 1.0e-3 * 34.77e0 * (r0 + 1.0e0) * np.sqrt(0.001e0 * ws2) * dens\n    gsm3 = 1.0e-6 * 0.3e0 * (tfhmax + 2.0e0) * ws2 * dens\n    calgsmass = gsm1 + gsm2 + gsm3','kg');
INSERT INTO fusion_alg VALUES(79,'calintercoil_surface','v','intercoil surface area','FusionFunc','calaintmass = 0.18e0 * st_f_b**2 * intercoil_surface * denstl','m^2');
INSERT INTO fusion_alg VALUES(80,'calrbvol','v','reactor building volume calculation','FusionFunc','rbw = 2.0e0 * wrbi + 2.0e0 * rbwt\n    rbl = drbi + 2.0e0 * rbwt\n    rbh = hrbi + rbrt + fndt\n    calrbvol = rbvfac * rbw * rbl * rbh','m3');
INSERT INTO fusion_alg VALUES(83,'calrmbvol','v','volume of maintenance and assembly building calculation ','FusionFunc',' tcw = shro - shri + 4.0e0 * trcl\n    tcl = 5.0e0 * tcw + 2.0e0 * hcwt\n    dcw = 2.0e0 * tcw + 1.0e0\n    hcw = shro - shri + 3.0e0 * hccl + 2.0e0\n    hcl = 3.0e0 * (shro - shri) + 4.0e0 * hccl + tcw\n    rmbw = hcw + dcw + 3.0e0 * hcwt\n    rmbl = hcl + 2.0e0 * hcwt\n    if wgt2 > 1.0e0:\n        wgts = wgt2\n    else:\n        wgts = shmf * shm / n_tf\n    cran = 9.41e-6 * wgts + 5.1e0\n    rmbh = (10.0e0 + shh+ trcl + cran+ stcl+ fndt)\n    tch = shh + stcl + fndt\n    calrmbvol = mbvfac * rmbw * rmbl * rmbh + tcw * tcl * tch','m3');
INSERT INTO fusion_alg VALUES(81,'calrndfuel','v','fuel burnup rate calculation','FusionFunc','fusionrate = fusionrate + (1.0e6*palpnb)/ (1.0e3 * ealphadt * echarge* vol)\n    fusrat= fusionrate*vol\n    calrndfuel = fusrat','reactions/ second ');
INSERT INTO fusion_alg VALUES(86,'caltargtm','v','mass of fuel calculation','FusionFunc','targtm = (gain* edrive * 3.0e0 * 1.67e-27 * 1.0e3/ (1.602e-19 * 17.6e6 * fburn))',NULL);
INSERT INTO fusion_alg VALUES(82,'calvolrci','v','internal volulme of reactor building calculation ','FusionFunc','calvolrci = rbvfac * 2.0e0 * wrbi * drbi * hrbi','m3');
INSERT INTO fusion_alg VALUES(84,'calwsvol','v','volume of warm shop building calculation ','FusionFunc','tcw = shro - shri + 4.0e0 * trcl\n    hcw = shro - shri + 3.0e0 * hccl + 2.0e0\n    hcl = 3.0e0 * (shro - shri) + 4.0e0 * hccl + tcw\n    dcw = 2.0e0 * tcw + 1.0e0\n    rmbw = hcw + dcw + 3.0e0 * hcwt\n    rmbl = hcl + 2.0e0 * hcwt\n    rmbw = hcw + dcw + 3.0e0 * hcwt\n    wsa = (rmbw + 7e0)*20+(rmbl*7)\n    if wgt2 > 1.0e0:\n        wgts = wgt2\n    else:\n        wgts = shmf * shm / n_tf\n    cran = 9.41e-6 * wgts + 5.1e0\n    rmbh = (10.0e0 + shh+ trcl + cran+ stcl+ fndt)\n    calwsvol = wsvfac*wsa*rmbh','m3');
INSERT INTO fusion_alg VALUES(87,'calwtgpd','v','mass of fuel used per day calcualtion','FusionFunc','ife = INTEGER(ife)\n    if ife ==1:\n        wtgpd = targtm*reprat*86400\n    else:\n        wtgpd = 2.0e0* rndfuel* afuel * umass* 1000.0e0* 86400.0e0',NULL);
INSERT INTO fusion_alg VALUES(96,'crfcdr','v','cdr_capital_recovery_factor_(M$)','FusionFunc','crfcdr = (fefcdr * discount_rate) / (fefcdr - 1.0e0)','million');
INSERT INTO fusion_alg VALUES(94,'crfcp','v','cp_capital_recovery_factor_(M$)','FusionFunc','itart = INTEGER(itart)\n    ife = INTEGER(ife)\n    if (itart == 1) and (ife != 1):\n        crfcp = (fefcp * discount_rate) / (fefcp - 1.0e0)\n    else: \n        crfcp = 0','million');
INSERT INTO fusion_alg VALUES(92,'crfdiv','v','div_capital_recovery_factor_(M$)','FusionFunc','ife = INTEGER(ife)\n    if ife == 1:\n        crfdiv = 0\n    else:\n        crfdiv = (fefdiv * discount_rate) / (fefdiv - 1.0e0)','million');
INSERT INTO fusion_alg VALUES(90,'crffwbl','v','fwb_capital_recovery_factor_(M$)','FusionFunc','crffwbl = (feffwbl * discount_rate) / (feffwbl - 1.0e0)','million');
INSERT INTO fusion_alg VALUES(95,'fefcdr','v','cdr_compound_interest_factor_(M$)','FusionFunc','fefcdr = (1.0e0 + discount_rate) ** cdrlife','N/A');
INSERT INTO fusion_alg VALUES(93,'fefcp','v','cp_compound_interest_factor_(M$)','FusionFunc',' itart = INTEGER(itart)\n    ife = INTEGER(ife)\n    if (itart == 1) and (ife != 1):\n        fefcp = (1.0e0 + discount_rate) ** cplife\n    else:\n        fefcp = 0','N/A');
INSERT INTO fusion_alg VALUES(91,'fefdiv','v','div_compound_interest_factor_(M$)','FusionFunc','ife = INTEGER(ife)\n    if ife == 1:\n        fefdiv = 0\n    else:\n        fefdiv = (1.0e0 + discount_rate) ** divlife','N/A');
INSERT INTO fusion_alg VALUES(89,'feffwbl','v','fwb_compound_interest_factor_(M$)','FusionFunc','feffwbl = (1+discount_rate)**fwbllife','N/A');
INSERT INTO fusion_alg VALUES(88,'fwbllife','v','fwb_operational_life_','FusionFunc','fwbllife = bktlife','years');
INSERT INTO fusion_alg VALUES(97,'stcalaintmass','v','stellarator intercoil structure mass calculation','Stellarator','aintmass = 0.18e0 * st_f_b**2 * intercoil_surface * denstl','kg');
INSERT INTO fusion_alg VALUES(99,'stcalclgsmass','v','stellarator gravity support structure for TF coil, PF coil and intercoil support systems calculation','Stellarator','clgsmass = 0.2*aintmass','kg');
INSERT INTO fusion_alg VALUES(98,'stcalintercoil_surface','v','stellarator intercoil surface area','Stellarator','intercoil_surface = (stella_config_coilsurface*st_f_r**2-tftort*stella_config_coillength * st_f_r * st_f_n)','m2');
