INSERT INTO algorithm VALUES(1,'sum_multi_accounts','c','sum of multiple accounts','PWRABRFunc','sum(account_1,account_2...account_n)','million','account1, account2.accountn',NULL);
INSERT INTO algorithm VALUES(4,'ptn_account','c','portion of account cost','PWRABRFunc','account_cost*portion','million','c_ref,prn_fac',NULL);
INSERT INTO algorithm VALUES(5,'unit_weights','c','unit cost of weight','PWRABRFunc','weight_of_carbon_steel*0.14+weight_of_stainless_steel*0.31','million','Csweight, Ssweight','0.140000, 0.310000');
INSERT INTO algorithm VALUES(6,'pump','v','cost per pump based on ref','PWRABRFunc','ref_cost_of_pump*(CH_of_pump/CH_of_ref)^scale_of_power','million','c_pump_ref,CH,CH_ref,scale',NULL);
INSERT INTO algorithm VALUES(7,'containment','c','containment calculation','PWRABRFunc','containment structure + equipment + others','million','NOT YET',NULL);
INSERT INTO algorithm VALUES(8,'MWth_scale','c','thermal power scale from pwr12be','PWRABRFunc','cost_of_ref*(thermal_power/thermal_power_of_ref)^thermal_power_scale','million','c_ref,mwth,scale','3431');
INSERT INTO algorithm VALUES(9,'unit_volume','c','cost by unit volume','PWRABRFunc','dollar_cost_per_unit_vol*vol/1000000','million','V1_unit_vol, V2_vol',NULL);
INSERT INTO algorithm VALUES(10,'dev_factor_ref','c','factor of the reference','PWRABRFunc','cost_of_ref*scale/factor','million','c_ref,scale,n',NULL);
INSERT INTO algorithm VALUES(11,'tur_exp_n','v','scaling exponent law ','PWRABRFunc','(-0.0032) *v_1+ 1.2497','1','p_in',NULL);
INSERT INTO algorithm VALUES(12,'esc_1987','c','escalate from 1987','PWRABRFunc','escalator*cost_in_1987','million','escalate_1987,refCost',NULL);
INSERT INTO algorithm VALUES(13,'cost_by_weight','c','per-unit mass costs','PWRABRFunc','tol_weight*coat_per_unit','million','tolweight, unitcost',NULL);
INSERT INTO algorithm VALUES(14,'default_0','c','default as 0','PWRABRFunc','set the total cost to 0','million',NULL,'0');
INSERT INTO algorithm VALUES(15,'rpv_mass','v','mass of RPV','PWRABRFunc','weight_of_carbon_steel+weight_of_stainless_steel','ton','c_221.12_cs_weight,c_221.12_ss_weight',NULL);
INSERT INTO algorithm VALUES(16,'unit_facility','c','per-unit facility costs','PWRABRFunc','no_of_facility*cost_per_facility','million','no_of_unit, unitcost',NULL);
INSERT INTO algorithm VALUES(17,'MWe_scale','c','electric power scale from pwr12be','PWRABRFunc','cost_of_ref*(electric_power/electric_power_of_ref)^electric_power_scale','million','c_ref,mwe,scale','1144');
INSERT INTO algorithm VALUES(18,'unit_weights_plate','c','unit cost of weight with plate installation','PWRABRFunc','weight_of_carbon_steel_plate_install*0.075+weight_of_stainless_steel*0.31','million','Csweight_plate, Ssweight','0.075000, 0.310000');
INSERT INTO algorithm VALUES(19,'esc_1978','c','escalate from 1978','PWRABRFunc','escalator*cost_in_1978','million','escalate_1978,refCost',NULL);
INSERT INTO algorithm VALUES(20,'total_weight_prn','c','unit cost of total weight by portion','PWRABRFunc','tol_weight*(portion_of_carbon_steel*0.075+portion_of_stainless_steel*0.31)*no_of_facility','million','V1_totweight, V2_csprn,V3_ssprn,V4_no_of_facility','0.075000, 0.310000');
INSERT INTO algorithm VALUES(21,'unit_weights_factor','c','unit cost of weight with factor','PWRABRFunc','(weight_of_carbon_steel_plate_install*0.075+weight_of_stainless_steel*0.31)*factor','million','Csweight, Ssweight,factor','0.075000, 0.310000');
INSERT INTO algorithm VALUES(22,'factor_sum','c','sum of multiple accounts with factor','PWRABRFunc','factor*prn*sum(account_2..account_n)','million','factor1, portion,account2.accountn',NULL);
INSERT INTO algorithm VALUES(23,'complex','c','complex algorithm','PWRABRFunc','simple cost','million','cost',NULL);
INSERT INTO algorithm VALUES(24,'MWth_lmfbrscale','c','thermal power scale from lmfbr','PWRABRFunc','cost_of_ref*(thermal_power/thermal_power_of_LMFBR)^thermal_power_scale','million','c_ref,mwth,scale','2287');
INSERT INTO algorithm VALUES(25,'MWreth_scale','c','rejected thermal power scale from pwr12be','PWRABRFunc','cost_of_ref*(rejected_hermal_power/rejected_thermal_power_of_LMFBR)^thermal_power_scale','million','c_ref,mwreth,scale','3800');
INSERT INTO algorithm VALUES(26,'Sgsum','c','sum the SG cost','PWRABRFunc','weight*unitcost*unit','million','sg_weight, c_unit, no_unit ',NULL);
INSERT INTO algorithm VALUES(28,'inside_rad','v','calculate inside radius','PWRABRFunc','radius_out-thickness','m','r_out, t',NULL);
INSERT INTO algorithm VALUES(29,'round_surface','v','calculate surface base on radius','PWRABRFunc','radius','m^2','r','PI');
INSERT INTO algorithm VALUES(30,'basemat_volume','v','calculate basemat volume base on surface','PWRABRFunc','basemat_surface*thickness','m^3','S,t',NULL);
INSERT INTO algorithm VALUES(31,'wall_height','v','calculate wall height base on total height','PWRABRFunc','total_height-roof_rad','m',NULL,NULL);
INSERT INTO algorithm VALUES(32,'walls_surface','v','calculate Walls surface','PWRABRFunc','Cont_H_wall_m*2*PI()*(Cont_rad_out_m+Cont_rad_in_m)','m^2',NULL,NULL);
INSERT INTO algorithm VALUES(33,'wall_volume','v','calculate Walls volume','PWRABRFunc','Cont_H_wall_m*PI()*(Cont_rad_out_m^2-Cont_rad_in_m^2)','m^3',NULL,NULL);
INSERT INTO algorithm VALUES(35,'roof_surface','v','calculate Roof surface','PWRABRFunc','0.5*4*PI()*(Cont_rad_out_m^2+Dome_rad_in_m^2)','m^2',NULL,NULL);
INSERT INTO algorithm VALUES(36,'roof_volume','v','calculate Roof volume','PWRABRFunc','0.5*4/3*PI()*(Cont_rad_out_m^3-Dome_rad_in_m^3)','m^3',NULL,NULL);
INSERT INTO algorithm VALUES(37,'tot_internal_volume','v','calculate Tot internal Volume','PWRABRFunc','(PI()*Cont_rad_in_m^2*Cont_H_wall_m)+(0.5*(4/3)*PI()*Dome_rad_in_m^3)','m^3',NULL,NULL);
INSERT INTO algorithm VALUES(38,'building_internal_volume','v','calculate Building internal volume','PWRABRFunc','Intern_tot_v_m3*(1-Void_fraction)','m^3',NULL,NULL);
INSERT INTO algorithm VALUES(39,'building_internal _surface','v','calculate Building internal surface','PWRABRFunc','2*Internal_v_m3/B11','m^2',NULL,NULL);
INSERT INTO algorithm VALUES(40,'volume_of_the_structures ','v','calculate volume of the structures ','PWRABRFunc','Basemat_v_m3+Walls_v_m3+Dome_v_m3+Internal_v_m3','m^3',NULL,NULL);
INSERT INTO algorithm VALUES(41,'Inside_liner_surface','v','calculate Inside liner surface','PWRABRFunc','(Cont_rad_in_m^2*PI())+(Cont_H_wall_m*2*PI()*Cont_rad_in_m)+(0.5*4*PI()*Dome_rad_in_m^2)','m^2',NULL,NULL);
INSERT INTO algorithm VALUES(42,'liner_Surface','v','calculate Liner Surface','PWRABRFunc','Inside_liner_s*liner_fraction','m^2',NULL,NULL);
INSERT INTO algorithm VALUES(43,'painted_surface','v','calculate painted surface','PWRABRFunc','Inside_liner_s+(Cont_H_wall_m*2*PI()*Cont_rad_out_m)+(0.5*4*PI()*Cont_rad_out_m^2)+Internal_s_m2','m^2',NULL,NULL);
INSERT INTO algorithm VALUES(44,'Inflation_rate','v','calculate Inflation rate','PWRABRFunc','1.03^(1996-1987)*CPI','1',NULL,NULL);
INSERT INTO algorithm VALUES(45,'unitcost_v_eedb_to_accert','v','unit cost volume from EEDB with inflation','PWRABRFunc','unitcost_EEDB_v*infl','dollar/m^3',NULL,NULL);
INSERT INTO algorithm VALUES(46,'unitcost_s_eedb_to_accert','v','unit cost surface from EEDB with inflation','PWRABRFunc','unitcost_EEDB_s*infl','dollar/m^2',NULL,NULL);
INSERT INTO algorithm VALUES(47,'tol_contaiment_ce_cost','v','total cost for each part of cotiament','PWRABRFunc','unitcost*number_of stucture_unit','dollar',NULL,NULL);
INSERT INTO algorithm VALUES(48,'sum_ce','v','sum of multiple costelement','PWRABRFunc','sum(cost_element_1,cost_element2,cost_element_n)','dollar',NULL,NULL);
INSERT INTO algorithm VALUES(49,'Yardwork_cost','c','the cost of the land 2017','PWRABRFunc','81.5*land_surface_area','dollar','land_surface_area','81.5');
INSERT INTO algorithm VALUES(50,'Reactor_containment_mat_cost','c','Reactor_containment_mat_cost','PWRABRFunc','130.8*containment_subVolume','dollar','containment_subVolume','130.8');
INSERT INTO algorithm VALUES(51,'Reactor_containment_lab_cost','c','Reactor_containment_lab_cost','PWRABRFunc','915.6*Containment_hole_volume','dollar','Containment_hole_volume','915.6');
INSERT INTO algorithm VALUES(52,'Building_and_utilities_mat_cost','c','Building_and_utilities_mat_cost','PWRABRFunc','6458.3*Turbine_building_surface_area','dollar','Turbine_building_surface_area','6458.3');
INSERT INTO algorithm VALUES(53,'Building_and_utilities_lab_cost','c','Building_and_utilities_lab_cost','PWRABRFunc','9843*Distance_to_utilities+10000*Number_of_shipping_containers','dollar','Distance_to_utilities, Number_of_shipping_containers','9843, 10000');
INSERT INTO algorithm VALUES(54,'Reactor_startup_facility_cost','c','Reactor_startup_facility_cost','PWRABRFunc','7600*Battery_capacity_required+1100','dollar','Battery_capacity_required','7600, 1100');
INSERT INTO algorithm VALUES(55,'Outer_vessel_mat_cost','c','Outer_vessel_mat_cost','PWRABRFunc','310000*primary_outer_vessel_SS_mass','dollar','primary_outer_vessel_SS_mass','310000');
INSERT INTO algorithm VALUES(56,'Outer_vessel_lab_cost','c','Outer_vessel_lab_cost','PWRABRFunc','14080*primary_outer_vessel_SS_mass','dollar','primary_outer_vessel_SS_mass','14080');
INSERT INTO algorithm VALUES(57,'Inner_vessel_cost','c','Inner_vessel_cost','PWRABRFunc','310000*primary_inner_vessel_SS_mass','dollar','primary_inner_vessel_SS_mass','310000');
INSERT INTO algorithm VALUES(58,'Reactivity_control_system_cost','c','Reactivity_control_system_cost','PWRABRFunc','950*B4C_total_neutron_poison_mass_Kg+610000*(Number_of_control_rod_drums+number_of_emergency_control_rods)','dollar','B4C_total_neutron_poison_mass_Kg, Number_of_control_rod_drums, number_of_emergency_control_rods','950, 610000');
INSERT INTO algorithm VALUES(59,'Reflector_cost','c','Reflector_cost','PWRABRFunc','310000*stainless_steel_316_reflector_mass+120000*Al2O3_reflector_mass+1000000*BeO_reflector_mass','dollar','stainless_steel_316_reflector_mass, Al2O3_reflector_mass, BeO_reflector_mass','310000, 120000, 1000000');
INSERT INTO algorithm VALUES(60,'Shield_cost','c','Shield_cost','PWRABRFunc','949.9*shield_B4C_mass','dollar','shield_B4C_mass','949.9');
INSERT INTO algorithm VALUES(61,'Moderator_cost','c','Moderator_cost','PWRABRFunc','310000*moderator_ZrH_mass','dollar','moderator_ZrH_mass','310000');
INSERT INTO algorithm VALUES(62,'cooling_heat_pipes_cost','c','cooling_heat_pipes_cost','PWRABRFunc','10000*number_of_core_cooling_heat_pipes*(1-mass_production_cost_reduction_factor)','dollar','number_of_core_cooling_heat_pipes, mass_production_cost_reduction_factor','10000');
INSERT INTO algorithm VALUES(63,'heat_exchangers_mat_cost','c','heat_exchangers_mat_cost','PWRABRFunc','50000*number_of_heat_exchangers','dollar','number_of_heat_exchangers','50000');
INSERT INTO algorithm VALUES(64,'heat_exchangers_lab_cost','c','heat_exchangers_lab_cost','PWRABRFunc','530000*number_of_heat_exchangers','dollar','number_of_heat_exchangers','530000');
INSERT INTO algorithm VALUES(65,'heat_exchangers_fac_cost','c','heat_exchangers_fac_cost','PWRABRFunc','120000*number_of_heat_exchangers*heat_exchangers_mass','dollar','number_of_heat_exchangers, heat_exchangers_mass','120000');
INSERT INTO algorithm VALUES(66,'instrumentation_contorl_cost','c','instrumentation_contorl_cost','PWRABRFunc','2000*number_of_IO_sensors+6500000','dollar','number_of_IO_sensors','2000');
INSERT INTO algorithm VALUES(67,'turb_and_elec_sys_cost','c','turb_and_elec_sys_cost','PWRABRFunc','282553*mwth+ 213800000*(pow(mwe/1144, 0.4) + pow(mwth/3431, 0.8))','dollar','mwth, mwe','282553, 1144, 0.4, 3431, 0.8');
