PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE `abr_account` (
  `ind` INTEGER DEFAULT NULL,
  `code_of_account` TEXT NOT NULL,
  `account_description` text,
  `total_cost` REAL DEFAULT NULL,
  `level` INTEGER DEFAULT NULL,
  `supaccount` text,
  `review_status` text,
  `prn` REAL DEFAULT NULL,
  `gncoa` text,
  `gn_level` INTEGER DEFAULT NULL,
  `gn_supaccount` text,
  `gn_ind` INTEGER DEFAULT NULL,
  PRIMARY KEY (`code_of_account`)
);
CREATE TABLE `abr_cost_element` (
  `ind` INTEGER NOT NULL ,
  `cost_element` text,
  `cost_2017` REAL DEFAULT NULL,
  `sup_cost_ele` text,
  `alg_name` text,
  `fun_unit` text,
  `variables` text,
  `account` text,
  `algno` text,
  `updated` INTEGER DEFAULT NULL,
  PRIMARY KEY (`ind`)
);
CREATE TABLE `abr_variable` (
  `ind` INTEGER NOT NULL ,
  `var_name` text,
  `var_description` text,
  `var_value` REAL DEFAULT NULL,
  `var_unit` text,
  `var_alg` text,
  `var_need` text,
  `v_linked` text,
  `user_input` INTEGER DEFAULT NULL,
  PRIMARY KEY (`ind`)
);
CREATE TABLE `account` (
  `ind` INTEGER DEFAULT NULL,
  `code_of_account` TEXT NOT NULL,
  `account_description` text,
  `total_cost` REAL DEFAULT NULL,
  `level` INTEGER DEFAULT NULL,
  `supaccount` text,
  `review_status` text,
  `prn` REAL DEFAULT NULL,
  `gncoa` text,
  `gn_level` INTEGER DEFAULT NULL,
  `gn_supaccount` text,
  `gn_ind` INTEGER DEFAULT NULL,
  PRIMARY KEY (`code_of_account`)
);
CREATE TABLE `cost_element` (
  `ind` INTEGER NOT NULL ,
  `cost_element` TEXT NOT NULL,
  `cost_2017` REAL DEFAULT NULL,
  `sup_cost_ele` text,
  `alg_name` text,
  `fun_unit` text,
  `variables` text,
  `account` text,
  `algno` text,
  `updated` INTEGER DEFAULT NULL,
  PRIMARY KEY (`ind`,`cost_element`)
);
CREATE TABLE `escalation` (
  `ind` INTEGER NOT NULL ,
  `name` TEXT NOT NULL,
  `description` text,
  `revision` text,
  `value` REAL DEFAULT NULL,
  `year_of_interest` datetime DEFAULT NULL,
  PRIMARY KEY (`ind`)
);
CREATE TABLE `facility` (
  `ind` INTEGER NOT NULL ,
  `name` TEXT NOT NULL,
  `description` text,
  `account` TEXT DEFAULT NULL,
  `references` text,
  `reference_year` datetime DEFAULT NULL,
  `year_of_interest` datetime DEFAULT NULL,
  `escalation_name` TEXT DEFAULT NULL,
  `escalation_factorsValue` REAL DEFAULT NULL,
  PRIMARY KEY (`ind`,`name`)
);
CREATE TABLE `fusion_acco` (
  `ind` INTEGER DEFAULT NULL,
  `code_of_account` TEXT NOT NULL,
