  `alg_description` text,
  `alg_python` text,
  `alg_formulation` text,
  `alg_units` text,
  PRIMARY KEY (`alg_name`)
);
CREATE TABLE `fusion_lcoe` (
  `ind` INTEGER DEFAULT NULL,
