CREATE TABLE algorithm (
  ind INTEGER,
  alg_name TEXT,
  alg_for TEXT,
  alg_description TEXT,
  alg_python TEXT,
  alg_formulation TEXT,
  alg_units TEXT,
  variables TEXT,
  constants TEXT
