CREATE TABLE lpsr_account (ind INTEGER, code_of_account TEXT NOT NULL, account_description TEXT, total_cost REAL, level INTEGER, supaccount TEXT, review_status TEXT, prn REAL, gncoa TEXT, gn_level INTEGER, gn_supaccount TEXT, gn_ind INTEGER, PRIMARY KEY (code_of_account));
CREATE TABLE lpsr_cost_element (ind INTEGER NOT NULL, cost_element TEXT, cost_2017 REAL, sup_cost_ele TEXT, alg_name TEXT, fun_unit TEXT, variables TEXT, account TEXT, algno TEXT, updated INTEGER, source_row_type TEXT, PRIMARY KEY (ind));
CREATE TABLE lpsr_variable (ind INTEGER NOT NULL, var_name TEXT, var_description TEXT, var_value REAL, var_unit TEXT, var_alg TEXT, var_need TEXT, v_linked TEXT, user_input INTEGER, PRIMARY KEY (ind));
CREATE TABLE lpsr_algorithm (
          ind INTEGER,
          alg_name TEXT,
          alg_for TEXT,
          alg_description TEXT,
          alg_python TEXT,
          alg_formulation TEXT,
          alg_units TEXT,
          variables TEXT,
          constants TEXT,
